{"content":"/* Print-in-place gimbal: outer ring on stand, middle ring, inner disc.
   Print orientation: flat (XY), +Z up, all bottoms on bed (Z=0).
   Outer OD 70mm. Clearances 0.5mm for PLA 0.4mm nozzle.
   Pivots: outer-middle about X (side pins), middle-disc about Y (front/back pins).
   Full 360 deg each, no supports (pin/socket bridges <=5mm declared).
*/
part = "assembly"; // [frame:Frame, middle:Middle, disc:Disc, assembly:Assembly]

cadverify_only = "";
module instance(name, part, unit = 1) {
    echo(cadverify_instance = [name, part, unit]);
    if (cadverify_only == "" || cadverify_only == name) children();
}

// ---- parameters ----
R_out_out = 35;      // outer ring outer radius (70 across)
R_out_in  = 30;      // outer ring inner radius
T         = 5;       // ring/disc thickness in Z
Zc        = 2.5;     // pivot axis height (T/2)
R_mid_out = 29.5;    // middle outer (0.5 gap to outer)
R_mid_in  = 25.5;    // middle inner (4 wall)
R_disc    = 25.0;    // disc radius (0.5 gap to middle)
pin_r  = 2.0;        // pin radius (d=4)
sock_r = 2.5;        // socket radius (d=5, 0.5 clearance)
foot_x = 4;          // half width of stand feet in X
foot_y0 = 33; foot_y1 = 41; // feet Y extents (+ side), mirrored for -
pin_mid_x0 = 27.5; pin_mid_x1 = 32;   // middle->outer pin X span (+ side)
sock_out_x0 = 29.9; sock_out_x1 = 33.9; // outer socket X span (+ side)
sock_mid_y0 = 25.4; sock_mid_y1 = 29.4; // middle socket Y span (+ side)
pin_disc_y0 = 23; pin_disc_y1 = 27;     // disc->middle pin Y span (+ side)

$fn = 128;

module frame() {
    difference() {
        union() {
            // outer ring
            difference() {
                cylinder(h=T, r=R_out_out);
                translate([0,0,-0.1]) cylinder(h=T+0.2, r=R_out_in);
            }
            // small stand: two feet at +-Y
            translate([-foot_x, foot_y0, 0]) cube([foot_x*2, foot_y1-foot_y0, T]);
            translate([-foot_x, -foot_y1, 0]) cube([foot_x*2, foot_y1-foot_y0, T]);
        }
        // pivot sockets about X (side bores, blind)
        translate([(sock_out_x0+sock_out_x1)/2, 0, Zc]) rotate([0,90,0]) cylinder(h=sock_out_x1-sock_out_x0, r=sock_r, center=true, $fn=48);
        translate([-(sock_out_x0+sock_out_x1)/2, 0, Zc]) rotate([0,90,0]) cylinder(h=sock_out_x1-sock_out_x0, r=sock_r, center=true, $fn=48);
    }
}

module middle() {
    difference() {
        union() {
            difference() {
                cylinder(h=T, r=R_mid_out);
                translate([0,0,-0.1]) cylinder(h=T+0.2, r=R_mid_in);
            }
            // pivot pins about X (protrude into outer sockets)
            translate([(pin_mid_x0+pin_mid_x1)/2, 0, Zc]) rotate([0,90,0]) cylinder(h=pin_mid_x1-pin_mid_x0, r=pin_r, center=true, $fn=48);
            translate([-(pin_mid_x0+pin_mid_x1)/2, 0, Zc]) rotate([0,90,0]) cylinder(h=pin_mid_x1-pin_mid_x0, r=pin_r, center=true, $fn=48);
        }
        // pivot sockets about Y (for disc pins, blind)
        translate([0, (sock_mid_y0+sock_mid_y1)/2, Zc]) rotate([90,0,0]) cylinder(h=sock_mid_y1-sock_mid_y0, r=sock_r, center=true, $fn=48);
        translate([0, -(sock_mid_y0+sock_mid_y1)/2, Zc]) rotate([90,0,0]) cylinder(h=sock_mid_y1-sock_mid_y0, r=sock_r, center=true, $fn=48);
    }
}

module disc() {
    union() {
        cylinder(h=T, r=R_disc);
        // pivot pins about Y
        translate([0, (pin_disc_y0+pin_disc_y1)/2, Zc]) rotate([90,0,0]) cylinder(h=pin_disc_y1-pin_disc_y0, r=pin_r, center=true, $fn=48);
        translate([0, -(pin_disc_y0+pin_disc_y1)/2, Zc]) rotate([90,0,0]) cylinder(h=pin_disc_y1-pin_disc_y0, r=pin_r, center=true, $fn=48);
    }
}

if (part == "frame") {
    echo(cadverify_spec = [
        ["bounds", [[-R_out_out, -foot_y1, 0], [R_out_out, foot_y1, T]]],
        ["bodies", 1],
        ["through_holes", 1],
        ["support_faces", [["bed", "-z", 800]]],
        ["overhangs_allowed", [
            ["pin bridge +X", [[29, -3, 0], [34, 3, T]]],
            ["pin bridge -X", [[-34, -3, 0], [-29, 3, T]]]
        ]],
        ["copies", 1],
        ["details", [
            ["stand+", "material", [[-foot_x, foot_y0, 0], [foot_x, foot_y1, T]], 0.9],
            ["stand-", "material", [[-foot_x, -foot_y1, 0], [foot_x, -foot_y0, T]], 0.9],
            ["gap1+", "void", [[-1, 29.55, 0], [1, 29.95, T]], 0.8],
            ["wall", "thickness", [36, 0, Zc], [-1, 0, 0], 5],
            ["floor", "thickness", [0, 32.5, -1], [0, 0, 1], 5],
            ["socket+X", "hole", [29.7, 0, Zc], [1, 0, 0], [[0, 5], [3, 5]]],
            ["socket-X", "hole", [-29.7, 0, Zc], [-1, 0, 0], [[0, 5], [3, 5]]]
        ]]
    ]);
    frame();
} else if (part == "middle") {
    echo(cadverify_spec = [
        ["bounds", [[-pin_mid_x1, -R_mid_out, 0], [pin_mid_x1, R_mid_out, T]]],
        ["bodies", 1],
        ["through_holes", 1],
        ["support_faces", [["bed", "-z", 400]]],
        ["overhangs_allowed", [
            ["pin+X", [[27, -2.5, 0], [32, 2.5, T]]],
            ["pin-X", [[-32, -2.5, 0], [-27, 2.5, T]]],
            ["socket+Y", [[-3, 25, 0], [3, 29.5, T]]],
            ["socket-Y", [[-3, -29.5, 0], [3, -25, T]]]
        ]],
        ["copies", 1],
        ["details", [
            ["pin+X", "material", [[29.5, -1.5, 1], [32, 1.5, 4]], 0.5],
            ["pin-X", "material", [[-32, -1.5, 1], [-29.5, 1.5, 4]], 0.5],
            ["gap2", "void", [[25.05, -1, 0], [25.45, 1, T]], 0.8],
            ["wall", "thickness", [30, 0, Zc], [-1, 0, 0], 4],
            ["floor", "thickness", [0, 27.5, -1], [0, 0, 1], 5],
            ["socket+Y", "hole", [0, 25.2, Zc], [0, 1, 0], [[0, 5], [3, 5]]],
            ["socket-Y", "hole", [0, -25.2, Zc], [0, -1, 0], [[0, 5], [3, 5]]]
        ]]
    ]);
    middle();
} else if (part == "disc") {
    echo(cadverify_spec = [
        ["bounds", [[-R_disc, -pin_disc_y1, 0], [R_disc, pin_disc_y1, T]]],
        ["bodies", 1],
        ["support_faces", [["bed", "-z", 1000]]],
        ["overhangs_allowed", [
            ["pin+Y", [[-2.5, 23, 0], [2.5, 27, T]]],
            ["pin-Y", [[-2.5, -27, 0], [2.5, -23, T]]]
        ]],
        ["copies", 1],
        ["details", [
            ["pin+Y", "material", [[-1.5, 23, 1], [1.5, 27, 4]], 0.5],
            ["pin-Y", "material", [[-1.5, -27, 1], [1.5, -23, 4]], 0.5],
            ["gap2x", "void", [[25.05, -1, 0], [25.45, 1, T]], 0.8],
            ["floor", "thickness", [0, 0, -1], [0, 0, 1], 5],
            ["edge", "thickness", [26, 0, Zc], [-1, 0, 0], 50]
        ]]
    ]);
    disc();
} else if (part == "assembly") {
    echo(cadverify_spec = [
        ["bounds", [[-R_out_out, -foot_y1, 0], [R_out_out, foot_y1, T]]],
        ["motions", [
            ["swing_middle", ["middle", "disc"], "rotate", [0, 0, Zc], [1, 0, 0], [0, 360]],
            ["spin_disc", ["disc"], "rotate", [0, 0, Zc], [0, 1, 0], [0, 360]]
        ]],
        ["print_in_place", 0.5],
        ["overhangs_allowed", [
            ["pin bridge X", [[-34, -3, 0], [34, 3, T]]],
            ["pin bridge Y", [[-3, -29.5, 0], [3, 29.5, T]]]
        ]],
        ["held", ["middle", "disc"]]
    ]);
    instance("frame", "frame") frame();
    instance("middle", "middle") middle();
    instance("disc", "disc") disc();
}
","path":"model.scad"}

{"content":"/* Print-in-place gimbal, vertical rings, no supports.
   Outer OD70 on small foot, middle + disc concentric, full 360 both axes.
   Print orientation: +Z up, all minima as modeled (frame 0, middle 5.5, disc 6.5).
   Clearance 0.5mm for PLA 0.4mm nozzle. T=6mm wall thickness.
*/
part = "assembly";
cadverify_only = "";
module instance(name, part, unit = 1) {
    echo(cadverify_instance = [name, part, unit]);
    if (cadverify_only == "" || cadverify_only == name) children();
}
Roo=35; Roi=30; Rmo=29.5; Rmi=25.5; Rd=25; T=6; H=T/2; Zc=35;
pin_r=2; sock_r=2.5;
$fn=128;
module ring(Ro,Ri) {
    translate([0,0,Zc]) rotate([90,0,0])
      difference(){
        cylinder(h=T,r=Ro,center=true);
        translate([0,0,0]) cylinder(h=T+0.4,r=Ri,center=true);
      }
}
module frame() {
    union(){
        ring(Roo,Roi);
        translate([-5,-11,0]) cube([10,22,4]);
    }
    // placeholder for diff below via difference wrapper
}
module frame_solid() {
    difference(){
        union(){
            ring(Roo,Roi);
            translate([-5,-11,0]) cube([10,22,4]);
        }
        // X sockets (outer-middle pivots)
        translate([31.5,0,Zc]) rotate([0,90,0]) cylinder(h=5,r=sock_r,center=true,$fn=48);
        translate([-31.5,0,Zc]) rotate([0,90,0]) cylinder(h=5,r=sock_r,center=true,$fn=48);
    }
}
module middle_solid() {
    difference(){
        union(){
            ring(Rmo,Rmi);
            // X pins
            translate([30.75,0,Zc]) rotate([0,90,0]) cylinder(h=5.5,r=pin_r,center=true,$fn=48);
            translate([-30.75,0,Zc]) rotate([0,90,0]) cylinder(h=5.5,r=pin_r,center=true,$fn=48);
        }
        // Z sockets top/bottom (middle-disc pivots)
        translate([0,0,8]) cylinder(h=4,r=sock_r,center=true,$fn=48);
        translate([0,0,62]) cylinder(h=4,r=sock_r,center=true,$fn=48);
    }
}
module disc_solid() {
    union(){
        translate([0,0,Zc]) rotate([90,0,0]) cylinder(h=T,r=Rd,center=true);
        // Z pins
        translate([0,0,9.25]) cylinder(h=5.5,r=pin_r,center=true,$fn=48);
        translate([0,0,60.75]) cylinder(h=5.5,r=pin_r,center=true,$fn=48);
    }
}
if (part=="frame") {
    echo(cadverify_spec=[
      ["bounds",[[-35,-11,0],[35,11,70]]],
      ["bodies",1],
      ["through_holes",1],
      ["support_faces",[["bed","-z",150]]],
      ["overhangs_allowed",[
        ["sock+X",[[28.5,-3,32],[34.5,3,38]]],
        ["sock-X",[[-34.5,-3,32],[-28.5,3,38]]]
      ]],
      ["copies",1],
      ["details",[
        ["stand","material",[[-5,-11,0],[5,11,4]],0.9],
        ["gapTop","void",[[-1,-1,64.55],[1,1,64.95]],0.8],
        ["wallY","thickness",[28,10,50],[0,-1,0],6],
        ["floorFoot","thickness",[0,8,-1],[0,0,1],4]
      ]]
    ]);
    frame_solid();
} else if (part=="middle") {
    echo(cadverify_spec=[
      ["bounds",[[-33.5,-3,5.5],[33.5,3,64.5]]],
      ["bodies",1],
      ["through_holes",1],
      ["overhangs_allowed",[
        ["pin+X",[[27.5,-2.5,32.5],[34,2.5,37.5]]],
        ["pin-X",[[-34,-2.5,32.5],[-27.5,2.5,37.5]]],
        ["sockBot",[[-3,-3,5],[3,3,11]]],
        ["sockTop",[[-3,-3,59],[3,3,64.5]]]
      ]],
      ["copies",1],
      ["details",[
        ["pinX","material",[[31,-1,34],[33,1,36]],0.8],
        ["gapTop","void",[[-1,-1,64.55],[1,1,64.95]],0.8],
        ["webX10","thickness",[10,0,6],[0,0,1],4.3]
      ]]
    ]);
    middle_solid();
} else if (part=="disc") {
    echo(cadverify_spec=[
      ["bounds",[[-25,-3,6.5],[25,3,63.5]]],
      ["bodies",1],
      ["overhangs_allowed",[
        ["pinBot",[[-2.5,-2.5,6],[2.5,2.5,12]]],
        ["pinTop",[[-2.5,-2.5,58],[2.5,2.5,64]]]
      ]],
      ["copies",1],
      ["details",[
        ["pinBot","material",[[-1,-1,7],[1,1,9]],0.8],
        ["gapTop","void",[[-1,-1,60.55],[1,1,60.95]],0.8],
        ["edgeX","thickness",[26,0,35],[-1,0,0],50]
      ]]
    ]);
    disc_solid();
} else if (part=="assembly") {
    echo(cadverify_spec=[
      ["bounds",[[-35,-11,0],[35,11,70]]],
      ["overhangs_allowed",[
        ["pinX",[[-34.5,-3,32],[34.5,3,38]]],
        ["pinZ",[[-3,-3,5],[3,3,64.5]]]
      ]],
      ["motions",[
        ["swing_middle",["middle","disc"],"rotate",[0,0,35],[1,0,0],[0,360]],
        ["spin_disc",["disc"],"rotate",[0,0,35],[0,0,1],[0,360]]
      ]],
      ["print_in_place",0.5],
      ["held",["middle","disc"]]
    ]);
    instance("frame","frame") frame_solid();
    instance("middle","middle") middle_solid();
    instance("disc","disc") disc_solid();
}
","path":"model.scad"}

{"content":"/* Print-in-place gimbal, vertical rings, no supports.
   Outer OD70 on small foot, middle + disc concentric, full 360 both axes.
   Each part exported resting on bed (min z=0); assembly centers all at Zc=35.
   Clearance 0.5mm for PLA 0.4mm nozzle. T=6mm wall thickness.
*/
part = "assembly";
cadverify_only = "";
module instance(name, part, unit = 1) {
    echo(cadverify_instance = [name, part, unit]);
    if (cadverify_only == "" || cadverify_only == name) children();
}
Roo=35; Roi=30; Rmo=29.5; Rmi=25.5; Rd=25; T=6; Zc=35;
pin_r=2; sock_r=2.5;
$fn=128;
// pivot at origin
module frame0() {
    difference(){
        union(){
            translate([0,0,0]) rotate([90,0,0])
              difference(){
                cylinder(h=T,r=Roo,center=true);
                cylinder(h=T+0.4,r=Roi,center=true);
              }
            translate([-5,-11,-35]) cube([10,22,4]);
        }
        translate([31.5,0,0]) rotate([0,90,0]) cylinder(h=5,r=sock_r,center=true,$fn=48);
        translate([-31.5,0,0]) rotate([0,90,0]) cylinder(h=5,r=sock_r,center=true,$fn=48);
    }
}
module middle0() {
    difference(){
        union(){
            translate([0,0,0]) rotate([90,0,0])
              difference(){
                cylinder(h=T,r=Rmo,center=true);
                cylinder(h=T+0.4,r=Rmi,center=true);
              }
            translate([30.75,0,0]) rotate([0,90,0]) cylinder(h=5.5,r=pin_r,center=true,$fn=48);
            translate([-30.75,0,0]) rotate([0,90,0]) cylinder(h=5.5,r=pin_r,center=true,$fn=48);
        }
        translate([0,0,-27]) cylinder(h=4,r=sock_r,center=true,$fn=48);
        translate([0,0,27]) cylinder(h=4,r=sock_r,center=true,$fn=48);
    }
}
module disc0() {
    union(){
        translate([0,0,0]) rotate([90,0,0]) cylinder(h=T,r=Rd,center=true);
        translate([0,0,-25.75]) cylinder(h=5.5,r=pin_r,center=true,$fn=48);
        translate([0,0,25.75]) cylinder(h=5.5,r=pin_r,center=true,$fn=48);
    }
}
if (part=="frame") {
    echo(cadverify_spec=[
      ["bounds",[[-35,-11,0],[35,11,70]]],
      ["bodies",1],
      ["through_holes",1],
      ["support_faces",[["bed","-z",150]]],
      ["overhangs_allowed",[
        ["sock+X",[[28.5,-3,32],[34.5,3,38]]],
        ["sock-X",[[-34.5,-3,32],[-28.5,3,38]]]
      ]],
      ["copies",1],
      ["details",[
        ["stand","material",[[-5,-11,0],[5,11,4]],0.9],
        ["gapTop","void",[[-1,-1,64.55],[1,1,64.95]],0.8],
        ["wallY","thickness",[28,10,50],[0,-1,0],6],
        ["floorFoot","thickness",[0,8,-1],[0,0,1],4]
      ]]
    ]);
    translate([0,0,Zc]) frame0();
} else if (part=="middle") {
    echo(cadverify_spec=[
      ["bounds",[[-33.5,-3,0],[33.5,3,59]]],
      ["bodies",1],
      ["through_holes",1],
      ["overhangs_allowed",[
        ["pin+X",[[27.5,-2.5,27],[34,2.5,32]]],
        ["pin-X",[[-34,-2.5,27],[-27.5,2.5,32]]],
        ["sockBot",[[-3,-3,0],[3,3,5.5]]],
        ["sockTop",[[-3,-3,53.5],[3,3,59]]]
      ]],
      ["copies",1],
      ["details",[
        ["pinX","material",[[31,-1,28.5],[33,1,30.5]],0.8],
        ["gapTop","void",[[-1,-1,59.05],[1,1,59.45]],0.8],
        ["wallY","thickness",[27,10,29.5],[0,-1,0],6]
      ]]
    ]);
    translate([0,0,29.5]) middle0();
} else if (part=="disc") {
    echo(cadverify_spec=[
      ["bounds",[[-25,-3,0],[25,3,57]]],
      ["bodies",1],
      ["overhangs_allowed",[
        ["pinBot",[[-2.5,-2.5,0],[2.5,2.5,5.5]]],
        ["pinTop",[[-2.5,-2.5,51.5],[2.5,2.5,57]]]
      ]],
      ["copies",1],
      ["details",[
        ["pinBot","material",[[-1,-1,1],[1,1,3]],0.8],
        ["gapAir","void",[[2.05,-0.4,54.5],[2.45,0.4,56.5]],0.8],
        ["edgeX","thickness",[26,0,28.5],[-1,0,0],50]
      ]]
    ]);
    translate([0,0,28.5]) disc0();
} else if (part=="assembly") {
    echo(cadverify_spec=[
      ["bounds",[[-35,-11,0],[35,11,70]]],
      ["overhangs_allowed",[
        ["pinX",[[-34.5,-3,32],[34.5,3,38]]],
        ["pinZ",[[-3,-3,5],[3,3,64.5]]]
      ]],
      ["motions",[
        ["swing_middle",["middle","disc"],"rotate",[0,0,35],[1,0,0],[0,360]],
        ["spin_disc",["disc"],"rotate",[0,0,35],[0,0,1],[0,360]]
